package com.supermercado.pos.ui;

import javax.swing.*;import java.awt.*;import com.supermercado.pos.util.*;
public class MenuPrincipalFrame extends JFrame {public MenuPrincipalFrame(){super("POS - Menú principal");setLayout(new GridLayout(0,2,8,8));agregar("Apertura de turno","TURNO_ABRIR",()->new AperturaTurnoFrame().setVisible(true));agregar("Punto de venta","VENTA_COBRAR",()->new PosFrame().setVisible(true));agregar("Corte intermedio","CORTE_INTERMEDIO",()->new CorteIntermedioDialog(this).setVisible(true));agregar("Reversión","REVERSION_SOLICITAR",()->new ReversionFrame().setVisible(true));agregar("Cierre de turno","TURNO_CERRAR",()->new CierreTurnoFrame().setVisible(true));agregar("Usuarios","USUARIO_ADMIN",()->new UsuariosFrame().setVisible(true));agregar("Roles","ROL_ADMIN",()->new RolesFrame().setVisible(true));agregar("Permisos","ROL_ADMIN",()->new AsignacionPermisosDialog(this).setVisible(true));agregar("Productos","CATALOGO_ADMIN",()->new ProductosFrame().setVisible(true));agregar("Cajas","CATALOGO_ADMIN",()->new CajasFrame().setVisible(true));JButton salir=new JButton("Cerrar sesión");salir.addActionListener(e->{Sesion.cerrar();dispose();new LoginFrame().setVisible(true);});add(salir);setSize(550,380);setLocationRelativeTo(null);setDefaultCloseOperation(EXIT_ON_CLOSE);}
 private void agregar(String texto,String permiso,Runnable r){JButton b=new JButton(texto);b.setEnabled(Sesion.getUsuario().tienePermiso(permiso));b.addActionListener(e->UI.accion(this,r));add(b);}}